java.util.function.Supplier<List<ProcessHandle>> running = () -> ProcessHandle.allProcesses()
        .filter(p -> p.info().user().map(user::equals).orElse(false))
        .filter(p -> state(java.nio.file.Path.of("/proc/" + p.pid() + "/stat")) != 'Z')
        .collect(java.util.stream.Collectors.toList());
for (int round = 0; round < 6; round++) {
    List<ProcessHandle> live = running.get();
    if (live.isEmpty()) {
        break;
    }
    for (ProcessHandle p : live) {
        if (round == 0) {
            p.destroy();
        } else {
            p.destroyForcibly();
        }
    }
    try {
        Thread.sleep(round == 0 ? 1000 : 200);
    } catch (InterruptedException e) {
        Thread.currentThread().interrupt();
        break;
    }
}
List<ProcessHandle> left = running.get();
if (!left.isEmpty()) {
    return left.size() + " process(es) would not end, pid " + left.get(0).pid();
}

